#ifndef GAME_CONTENT_TYPES_H
#define GAME_CONTENT_TYPES_H

/* Types of the game content. The tables themselves (src/generated/content.c) are
 * generated by tools/gen_data.py from the CSV files of data/ (Pet Simulator 99 wiki data). */

#include <stdbool.h>
#include <stdint.h>
#include "../gfx/gfx.h"

/* Game rarity tiers. Every egg pet is "Basic" on the PS99 wiki, so the tier comes
 * from the pet's hatch chance in its home egg (see tools/gen_data.py). */
typedef enum { TIER_BASIC, TIER_RARE, TIER_EPIC, TIER_LEGENDARY, TIER_MYTHICAL, TIER_COUNT } tier_t;

typedef struct {
  const char *name;
  const sprite_t *sprite; /* 48x48 */
  double power;           /* damage per second when equipped */
  uint8_t tier;
  uint8_t egg; /* home egg: the last egg that contains it */
} pet_t;

typedef struct {
  uint8_t pet;
  bool secret;     /* chance shown "??" on the wiki */
  uint32_t weight; /* out of EGG_WEIGHT_TOTAL, the weights of an egg sum exactly to it */
} egg_slot_t;

typedef struct {
  const char *name;
  const sprite_t *sprite; /* 48x48 */
  double cost;
  uint8_t zone;
  uint8_t number; /* egg number in Pet Simulator 99 */
  uint8_t first_slot, slot_count;
} egg_t;

typedef struct {
  const char *name;
  const sprite_t *thumb; /* 64x36 screenshot of the area */
  double cost;           /* price to unlock, in coins */
  color_t sky_top, sky_bottom; /* background gradient */
  color_t accent;              /* zone badge in the top bar */
  uint8_t first_egg, egg_count;
  double pile_hp;     /* HP of a coin pile in this zone (other breakables are multiples) */
  double pile_reward; /* coins of a coin pile */
} zone_t;

#endif
